<script setup>import{reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{useAuthStore}from'../stores/auth.js';const router=useRouter(),route=useRoute(),auth=useAuthStore(),loading=ref(false),form=reactive({username:'user01',password:'123456'});const submit=async()=>{loading.value=true;try{await auth.login(form);ElMessage.success('欢迎回来');router.push(route.query.redirect||'/')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}};const demo=u=>{form.username=u;form.password='123456';submit()}</script>
<template><div class="auth-page"><div class="auth-visual" :style="{backgroundImage:`linear-gradient(rgba(8,42,49,.15),rgba(8,42,49,.65)),url(/uploads/demo/banners/banner-003.png)`}"><router-link to="/" class="auth-logo"><img src="/uploads/demo/logo.png">山海迹</router-link><div><span>WELCOME BACK</span><h1>下一次出发，<br>从收藏的灵感继续</h1><p>登录后可以点赞、收藏、评论、关注创作者，并把公开路线复制成自己的计划。</p></div></div><div class="auth-panel"><div class="auth-box"><span class="eyebrow">MEMBER LOGIN</span><h2>登录山海迹</h2><p>使用账号继续你的旅行计划</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="form.username" size="large" placeholder="用户名"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password size="large" placeholder="密码" @keyup.enter="submit"/></el-form-item><el-button type="primary" size="large" :loading="loading" class="full" @click="submit">登录</el-button></el-form><div class="demo-accounts"><b>快速体验</b><button @click="demo('user01')">普通用户</button><button @click="demo('creator01')">创作者</button><button @click="demo('auditor01')">审核员</button></div><p class="switch">还没有账号？<router-link to="/register">立即注册</router-link></p></div></div></div></template>
<style scoped src="../assets/auth.css"></style>

